const roles = pm.response.json().items;
for (const role of roles) {
  pm.collectionVariables.set(role.key + "_roleId", role._id);
}

const Crypto = require('crypto-js');
const eventId = pm.variables.replaceIn("{{$guid}}");
const externalId = pm.collectionVariables.get("externalId") || "ext_demo";
const rawBody = JSON.stringify({
  eventId,
  externalId,
  status: "PAID",
  sequence: 1,
  occurredAt: new Date().toISOString()
});
pm.collectionVariables.set("eventId", eventId);
pm.collectionVariables.set("externalId", externalId);
pm.variables.set("webhookRawBody", rawBody);
pm.variables.set(
  "webhookSignature",
  Crypto.HmacSHA256(rawBody, pm.variables.get("billportSharedSecret")).toString()
);

const Crypto = require('crypto-js');
const eventId = pm.variables.replaceIn("{{$guid}}");
const externalId = pm.collectionVariables.get("externalId") || "ext_demo";
const rawBody = JSON.stringify({
  eventId,
  externalId,
  status: "PAID",
  sequence: 1,
  occurredAt: new Date().toISOString()
});
const signature = Crypto.HmacSHA256(rawBody, pm.variables.get("billportSharedSecret")).toString();
const tamperedSignature = signature.endsWith("0")
  ? signature.slice(0, -1) + "1"
  : signature.slice(0, -1) + "0";
pm.variables.set("tamperedRawBody", rawBody);
pm.variables.set("tamperedSignature", tamperedSignature);

const items = pm.response.json().items;
if (items.length > 0) {
  pm.collectionVariables.set("threadId", items[0].threadId);
  pm.collectionVariables.set("chatDealId", items[0].dealId);
}

const Crypto = require('crypto-js');
const reference = pm.variables.replaceIn("{{$guid}}");
const rawBody = JSON.stringify({
  reference,
  customer: { id: pm.collectionVariables.get("customerId"), name: "Acme Corp" },
  amount: 18000,
  currency: "USD",
  lineItems: [],
  issuedAt: new Date().toISOString()
});
pm.variables.set("billportRawBody", rawBody);
pm.variables.set(
  "billportSignature",
  Crypto.HmacSHA256(rawBody, pm.variables.get("billportSharedSecret")).toString()
);

const body = pm.response.json();
if (body.externalId) {
  pm.collectionVariables.set("externalId", body.externalId);
}
